def norm(comp):
    rs=[r for r,c in comp]; cs=[c for r,c in comp]
    mr,mc=min(rs),min(cs)
    return tuple(sorted((r-mr,c-mc) for r,c in comp))
def transform(g):
    bg=g[0][0]
    from collections import Counter
    from collections import defaultdict
    cells=Counter(); 
    for row in g:
        for v in row: 
            if v!=bg: cells[v]+=1
    S=max(cells,key=lambda c:cells[c])
    # objects per color
    seen=set(); allo=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]!=bg and (i,j) not in seen:
                col=g[i][j]; st=[(i,j)]; comp=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen or not(0<=y<len(g) and 0<=x<len(g[0])) or g[y][x]!=col: continue
                    seen.add((y,x)); comp.append((y,x)); st+=[(y+1,x),(y-1,x),(y,x+1),(y,x-1)]
                allo.append((col,comp))
    norms=defaultdict(list)
    for col,comp in allo: norms[norm(comp)].append((col,comp))
    cands=[(col,comp) for col,comp in allo if col==S and len(norms[norm(comp)])>1]
    if not cands: cands=[(col,comp) for col,comp in allo if col==S]
    col,comp=max(cands,key=lambda cc:min(r for r,c in cc[1]))  # topmost
    shapes=defaultdict(int)
    for c,_ in allo: shapes[c]+=1
    tgt=min((c for c in shapes if c!=S), key=lambda c:(shapes[c],c))
    out=[r[:] for r in g]
    for y,x in comp: out[y][x]=tgt
    return out
