def twins(g,bg):
    comps=objs2(g,bg)
    D=defaultdict(list)
    for col,comp in comps: D[norm(comp)].append((col,comp))
    pairs=[]
    for k,v in D.items():
        if len(v)>1: pairs.append((len(k),[(c,min(r for r,_ in cp),min(c for _,r in cp)) for c,cp in v]))
    return sorted(pairs,reverse=True)
