def shapes8(g,bg):
    Hh,Ww=len(g),len(g[0]); seen=set(); out=[]
    for r in range(Hh):
        for c in range(Ww):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; comp=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in comp: continue
                    comp.add((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<Hh and 0<=y<Ww and g[x][y]==col and (x,y) not in comp: st.append((x,y))
                seen|=comp
                rs=[a for a,_ in comp]; cs=[b for _,b in comp]
                out.append(dict(col=col,size=len(comp),r0=min(rs),c0=min(cs),r1=max(rs),c1=max(cs),cells=comp,sil=norm(comp)))
    return out
